#include <stdio.h>
#include <string.h>

#define MAXL 100
#define MAXC 100
#define MAXV 676

int L, C;
int grid[MAXL][MAXC];
int present[MAXV];
int knownVar[MAXV];
__int128 valueVar[MAXV];
long long rowTarget[MAXL], colTarget[MAXC];

void print128(__int128 x) {
    if (x == 0) {
        putchar('0');
        return;
    }
    if (x < 0) {
        putchar('-');
        x = -x;
    }
    char buf[64];
    int n = 0;
    while (x > 0) {
        buf[n++] = (char)('0' + (int)(x % 10));
        x /= 10;
    }
    while (n > 0) {
        putchar(buf[--n]);
    }
}

int solveRow(int i) {
    __int128 knownSum = 0;
    int unknownVar = -1;
    int coeff = 0;
    int distinct = 0;

    for (int j = 0; j < C; j++) {
        int v = grid[i][j];
        if (knownVar[v]) {
            knownSum += valueVar[v];
        } else {
            if (distinct == 0) {
                unknownVar = v;
                coeff = 1;
                distinct = 1;
            } else if (v == unknownVar) {
                coeff++;
            } else {
                distinct = 2;
            }
        }
    }

    if (distinct == 1) {
        valueVar[unknownVar] = ((__int128)rowTarget[i] - knownSum) / coeff;
        knownVar[unknownVar] = 1;
        return 1;
    }

    return 0;
}

int solveCol(int j) {
    __int128 knownSum = 0;
    int unknownVar = -1;
    int coeff = 0;
    int distinct = 0;

    for (int i = 0; i < L; i++) {
        int v = grid[i][j];
        if (knownVar[v]) {
            knownSum += valueVar[v];
        } else {
            if (distinct == 0) {
                unknownVar = v;
                coeff = 1;
                distinct = 1;
            } else if (v == unknownVar) {
                coeff++;
            } else {
                distinct = 2;
            }
        }
    }

    if (distinct == 1) {
        valueVar[unknownVar] = ((__int128)colTarget[j] - knownSum) / coeff;
        knownVar[unknownVar] = 1;
        return 1;
    }

    return 0;
}

int main(void) {
    if (scanf("%d %d", &L, &C) != 2) return 0;

    char name[10];
    long long s;

    for (int i = 0; i < L; i++) {
        for (int j = 0; j < C; j++) {
            scanf("%s", name);
            int id = (name[0] - 'a') * 26 + (name[1] - 'a');
            grid[i][j] = id;
            present[id] = 1;
        }
        scanf("%lld", &s);
        rowTarget[i] = s;
    }

    for (int j = 0; j < C; j++) {
        scanf("%lld", &s);
        colTarget[j] = s;
    }

    while (1) {
        int solved = 0;

        for (int i = 0; i < L; i++) {
            if (solveRow(i)) {
                solved = 1;
                break;
            }
        }

        if (!solved) {
            for (int j = 0; j < C; j++) {
                if (solveCol(j)) {
                    solved = 1;
                    break;
                }
            }
        }

        if (!solved) break;
    }

    for (int id = 0; id < MAXV; id++) {
        if (present[id]) {
            char a = (char)('a' + id / 26);
            char b = (char)('a' + id % 26);
            printf("%c%c ", a, b);
            print128(valueVar[id]);
            putchar('\n');
        }
    }

    return 0;
}
